"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import { useFieldContext } from "./field";

export interface CheckboxProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "size"> {
  label?: React.ReactNode;
  /** Extra uitleg onder het label. */
  description?: React.ReactNode;
  /** Derde staat: gedeeltelijk aangevinkt. */
  indeterminate?: boolean;
  size?: "sm" | "md";
}

/** Checkbox — eigen vormgeving bovenop een echte <input type="checkbox">. */
export const Checkbox = React.forwardRef<HTMLInputElement, CheckboxProps>(function Checkbox(
  { label, description, indeterminate, size = "md", className, id, disabled, ...rest },
  ref
) {
  const context = useFieldContext();
  const autoId = React.useId();
  const inputId = id ?? context?.id ?? `lui-checkbox-${autoId}`;
  const inner = React.useRef<HTMLInputElement | null>(null);

  React.useEffect(() => {
    if (inner.current) inner.current.indeterminate = Boolean(indeterminate);
  }, [indeterminate]);

  const control = (
    <span className={cn("lui-checkbox", `lui-checkbox-${size}`)}>
      <input
        ref={(node) => {
          inner.current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) (ref as React.MutableRefObject<HTMLInputElement | null>).current = node;
        }}
        id={inputId}
        type="checkbox"
        className="lui-checkbox-input"
        disabled={disabled ?? context?.disabled}
        {...rest}
      />
      <span className="lui-checkbox-box" aria-hidden="true">
        <Icon name={indeterminate ? "minus" : "check"} size={size === "sm" ? 11 : 13} strokeWidth={3} />
      </span>
    </span>
  );

  if (!label && !description) {
    return <span className={cn("lui-checkbox-standalone", className)}>{control}</span>;
  }

  return (
    <label
      className={cn("lui-checkbox-row", disabled && "lui-checkbox-row-disabled", className)}
      htmlFor={inputId}
    >
      {control}
      <span className="lui-checkbox-text">
        {label && <span className="lui-checkbox-label">{label}</span>}
        {description && <span className="lui-checkbox-description">{description}</span>}
      </span>
    </label>
  );
});

/* ============================ Checkbox ============================ */
.lui-checkbox { position: relative; display: inline-grid; place-items: center; flex: none; }
.lui-checkbox-input {
  position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer;
  width: 100%; height: 100%;
}
.lui-checkbox-input:disabled { cursor: not-allowed; }

.lui-checkbox-box {
  display: grid; place-items: center;
  width: 18px; height: 18px; border-radius: var(--r-xs);
  background: var(--surface); border: 1.5px solid var(--border-strong);
  color: var(--accent-fg); pointer-events: none;
  transition: background var(--dur-fast), border-color var(--dur-fast), box-shadow var(--dur-fast);
}
.lui-checkbox-box svg { opacity: 0; transform: scale(.7); transition: opacity var(--dur-fast), transform var(--dur-fast); }
.lui-checkbox-sm .lui-checkbox-box { width: 15px; height: 15px; }

.lui-checkbox-input:hover:not(:disabled) + .lui-checkbox-box { border-color: var(--text-3); }
.lui-checkbox-input:focus-visible + .lui-checkbox-box { border-color: var(--accent); box-shadow: var(--ring); }
.lui-checkbox-input:checked + .lui-checkbox-box,
.lui-checkbox-input:indeterminate + .lui-checkbox-box {
  background: var(--accent); border-color: var(--accent);
}
.lui-checkbox-input:checked + .lui-checkbox-box svg,
.lui-checkbox-input:indeterminate + .lui-checkbox-box svg { opacity: 1; transform: none; }
.lui-checkbox-input:disabled + .lui-checkbox-box { background: var(--surface-3); border-color: var(--border); }
.lui-checkbox-input:disabled:checked + .lui-checkbox-box { background: var(--text-3); border-color: var(--text-3); }

.lui-checkbox-row {
  display: flex; align-items: flex-start; gap: 10px; cursor: pointer;
  padding: 1px 0;
}
.lui-checkbox-row-disabled { cursor: not-allowed; opacity: .6; }
.lui-checkbox-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.lui-checkbox-label { font-size: 13.5px; font-weight: 550; color: var(--text); line-height: 1.35; }
.lui-checkbox-description { font-size: var(--fs-sm); color: var(--text-3); line-height: 1.45; }

/* ---------- Motion: vinkje springt, vakje krijgt een kort golfje ---------- */
.lui-checkbox-box svg { transition: opacity var(--dur-fast), transform .3s var(--ease-pop); transform: scale(.4) rotate(-20deg); }
.lui-checkbox-input:checked + .lui-checkbox-box { animation: lui-check-pulse .45s var(--ease-out); }
@keyframes lui-check-pulse {
  from { box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 45%, transparent); }
  to { box-shadow: 0 0 0 7px transparent; }
}
.lui-checkbox-input:active:not(:disabled) + .lui-checkbox-box { transform: scale(.9); }
.lui-checkbox-box { transition: background var(--dur-fast), border-color var(--dur-fast), box-shadow var(--dur-fast), transform .2s var(--ease-pop); }
